def decide(recipient_reputation, round_num, my_history):
    # Compute overall own cooperation rate (default 0.5 if empty)
    if len(my_history) == 0:
        own_rate = 0.5
    else:
        own_rate = sum(my_history) / len(my_history)

    # Base threshold: more cooperative -> more trusting (lower threshold)
    threshold = 0.6 - 0.4 * own_rate   # range [0.2, 0.6]

    # Early rounds: more cautious
    if round_num <= 5:
        threshold += 0.1
    # Late rounds: slightly more forgiving
    if round_num > 12:
        threshold -= 0.05

    # If we defected last round, become more cautious (use my_history[-1])
    if len(my_history) > 0 and not my_history[-1]:
        threshold += 0.1

    # Defect if reputation not high enough
    return recipient_reputation > threshold

def evaluate(current_reputation, observation, my_history, round_num):
    # Adaptive learning rate based on how certain we currently are about the agent.
    # - If reputation is extreme (|rep| > 0.8), we are confident, so small update.
    # - If reputation is moderate (0.4 < |rep| <= 0.8), standard update.
    # - If reputation is near zero (|rep| <= 0.4), we are uncertain, so larger update.
    action = observation['action']
    signal = 1.0 if action == 'cooperate' else -1.0
    certainty = abs(current_reputation)
    if certainty > 0.8:
        learning_rate = 0.05
    elif certainty > 0.4:
        learning_rate = 0.1
    else:
        learning_rate = 0.2
    new_reputation = (1 - learning_rate) * current_reputation + learning_rate * signal
    return max(-1.0, min(1.0, new_reputation))

def decide(recipient_reputation, round_num, my_history):
    # Sliding window of own recent cooperations (last 4 actions)
    window_size = 4
    recent_own = my_history[-window_size:] if len(my_history) >= window_size else my_history[:]
    recent_coop_count = sum(1 for action in recent_own if action)

    # Decision logic that is active across all reputation and round ranges:
    # - Early game (rounds 1-9): cooperate unless reputation is very negative
    #   or we have cooperated too much recently.
    # - Mid game (rounds 10-19): cooperate only if reputation is at least slightly positive.
    # - Late game (rounds 20+): cooperate only if reputation is high.
    if round_num < 10:
        if recipient_reputation > -0.3 and recent_coop_count <= 2:
            return True
        else:
            return False
    elif round_num < 20:
        if recipient_reputation > 0.1 and recent_coop_count <= 1:
            return True
        else:
            return False
    else:
        if recipient_reputation > 0.6 and recent_coop_count <= 1:
            return True
        else:
            return False
